package com.zig.antar.render

import com.zig.antar.config.AntarSimulationSettings
import java.io.ByteArrayInputStream
import java.util.Locale
import java.util.zip.GZIPInputStream

/**
 * Decodes and hosts the bundled WebGL2 Kerr-Schild null-geodesic ray-tracing simulation,
 * stripping all built-in HTML chrome and attaching a lightweight native telemetry & camera bridge
 * (`window.__antarBridge` <-> `window.AntarHostBridge`).
 */
object AntarSimulationPayload {

    const val HOST_BASE_ORIGIN: String = "https://appassets.androidplatform.net/assets/"

    /** Unmodified HTML decoded from [KERR_SIMULATION_GZIP_B64]. Works on both Android and plain JVM tests. */
    val rawSimulationHtml: String by lazy {
        val compressed = decodeBase64RFC4648(KERR_SIMULATION_GZIP_B64)
        GZIPInputStream(ByteArrayInputStream(compressed)).bufferedReader(Charsets.UTF_8).use { it.readText() }
    }

    /** Base URL carrying initial query parameters so the simulation boots directly into [settings]. */
    fun buildBaseUrl(settings: AntarSimulationSettings): String =
        "$HOST_BASE_ORIGIN?${settings.toInitialQueryString()}"

    /**
     * Produces the hosted HTML with all raw HTML controls hidden and `window.__antarBridge`
     * installed before `</body>`.
     */
    fun buildHostedHtml(): String = hostedSimulationHtml

    private val hostedSimulationHtml: String by lazy {
        val raw = applyMobileWebViewFixes(rawSimulationHtml)
        val anchor = "</body>"
        val idx = raw.lastIndexOf(anchor)
        check(idx > 0) { "Simulation HTML is missing closing </body> tag" }
        buildString(raw.length + NATIVE_CHROME_AND_BRIDGE.length + 16) {
            append(raw, 0, idx)
            append(NATIVE_CHROME_AND_BRIDGE)
            append(raw, idx, raw.length)
        }
    }

    /**
     * Applies narrowly-scoped fixes to the bundled standalone page without changing its source
     * asset: Android WebView may expose an empty document URL, and some mobile GPUs do not support
     * linear filtering of half-float textures or complete all render targets as expected.
     */
    private fun applyMobileWebViewFixes(source: String): String {
        val replacements = listOf(
            // Every procedural star layer shares this angular sigma. Keeping 60% of the original
            // radius makes every star exactly 40% smaller without changing its flux or lensing.
            "const float SIG_STAR = 0.00006;" to
                "const float SIG_STAR = 0.000036;",
            "const q=new URLSearchParams(location.search);" to
                "const q=new URLSearchParams(location.search || new URL(document.baseURI).search);",
            "if(location.search!==('?'+q.toString())) history.replaceState(null,'',location.pathname+'?'+q.toString()+location.hash);" to
                "if(location.search!==('?'+q.toString())) { try { history.replaceState(null,'',location.pathname+'?'+q.toString()+location.hash); } catch (_) {} }",
            "const qs = new URLSearchParams(location.search);" to
                "const qs = new URLSearchParams(location.search || new URL(document.baseURI).search);",
            "function fail(msg) {\n    const e = $('#error');" to
                "function fail(msg) {\n    try { if (window.AntarHostBridge) window.AntarHostBridge.onRuntimeError(String(msg)); } catch (_) {}\n    const e = $('#error');",
            "  gl.getExtension('OES_texture_float_linear');" to
                "  const floatLinear = !!gl.getExtension('OES_texture_float_linear');",
            "gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, filter || gl.LINEAR);" to
                "gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, filter || (floatLinear ? gl.LINEAR : gl.NEAREST));",
            "gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, filter || gl.LINEAR);" to
                "gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, filter || (floatLinear ? gl.LINEAR : gl.NEAREST));",
            "gl.texParameteri(gl.TEXTURE_CUBE_MAP, gl.TEXTURE_MIN_FILTER, gl.LINEAR_MIPMAP_LINEAR);" to
                "gl.texParameteri(gl.TEXTURE_CUBE_MAP, gl.TEXTURE_MIN_FILTER, floatLinear ? gl.LINEAR_MIPMAP_LINEAR : gl.NEAREST_MIPMAP_NEAREST);",
            "gl.texParameteri(gl.TEXTURE_CUBE_MAP, gl.TEXTURE_MAG_FILTER, gl.LINEAR);" to
                "gl.texParameteri(gl.TEXTURE_CUBE_MAP, gl.TEXTURE_MAG_FILTER, floatLinear ? gl.LINEAR : gl.NEAREST);",
            "      gl.framebufferTexture2D(gl.FRAMEBUFFER, gl.COLOR_ATTACHMENT0, gl.TEXTURE_CUBE_MAP_POSITIVE_X + f, skyTex, 0);" to
                "      gl.framebufferTexture2D(gl.FRAMEBUFFER, gl.COLOR_ATTACHMENT0, gl.TEXTURE_CUBE_MAP_POSITIVE_X + f, skyTex, 0);\n      const skyStatus = gl.checkFramebufferStatus(gl.FRAMEBUFFER);\n      if (skyStatus !== gl.FRAMEBUFFER_COMPLETE) { const msg = 'WebGL sky framebuffer incomplete: 0x' + skyStatus.toString(16); fail(msg); throw new Error(msg); }",
            "    gl.framebufferTexture2D(gl.FRAMEBUFFER, gl.COLOR_ATTACHMENT0, gl.TEXTURE_2D, tex, 0);\n    return { tex, fb, w, h };" to
                "    gl.framebufferTexture2D(gl.FRAMEBUFFER, gl.COLOR_ATTACHMENT0, gl.TEXTURE_2D, tex, 0);\n    const status = gl.checkFramebufferStatus(gl.FRAMEBUFFER);\n    if (status !== gl.FRAMEBUFFER_COMPLETE) { const msg = 'WebGL framebuffer incomplete: 0x' + status.toString(16); fail(msg); throw new Error(msg); }\n    return { tex, fb, w, h };",
            "    gl.drawBuffers([gl.COLOR_ATTACHMENT0, gl.COLOR_ATTACHMENT1]);\n    neighRT = { mu, sig, fb: nfb };" to
                "    gl.drawBuffers([gl.COLOR_ATTACHMENT0, gl.COLOR_ATTACHMENT1]);\n    const mrtStatus = gl.checkFramebufferStatus(gl.FRAMEBUFFER);\n    if (mrtStatus !== gl.FRAMEBUFFER_COMPLETE) { const msg = 'WebGL MRT framebuffer incomplete: 0x' + mrtStatus.toString(16); fail(msg); throw new Error(msg); }\n    neighRT = { mu, sig, fb: nfb };",
            "  outColor = vec4(col, escaped ? step(0.0005, max(Acc, max(col.r, max(col.g, col.b)))) : 1.0);" to
                "  if (any(isnan(col)) || any(isinf(col))) col = vec3(0.0);\n  col = clamp(col, vec3(0.0), vec3(60000.0));\n  outColor = vec4(col, escaped ? step(0.0005, max(Acc, max(col.r, max(col.g, col.b)))) : 1.0);",
            "  outColor = vec4(itm(o), oa);" to
                "  vec3 safeOut = itm(o);\n  if (any(isnan(safeOut)) || any(isinf(safeOut))) safeOut = vec3(0.0);\n  outColor = vec4(clamp(safeOut, vec3(0.0), vec3(60000.0)), clamp(oa, 0.0, 1.0));"
        )
        var patched = source
        replacements.forEach { (old, replacement) ->
            check(patched.contains(old)) { "Bundled simulation patch anchor missing: ${old.take(72)}" }
            patched = patched.replaceFirst(old, replacement)
        }
        return patched
    }

    /** Formats a JSON payload for `window.__antarBridge.applySettings(...)`. */
    fun buildSettingsJson(
        settings: AntarSimulationSettings,
        panXDp: Double,
        panYDp: Double,
        dockShiftDp: Double,
        yawRad: Double,
        pitchRad: Double
    ): String {
        val s = settings.normalize()
        fun num(v: Double, d: Int = 5): String = String.format(Locale.US, "%.${d}f", v)
        return buildString(512) {
            append('{')
            append("\"object\":\"${s.objectMode.jsKey}\",")
            append("\"mode\":\"${s.cameraMode.jsKey}\",")
            append("\"spin\":${num(s.spin, 4)},")
            append("\"mass\":\"${s.massPreset.jsKey}\",")
            append("\"az\":${num(s.azimuthDeg, 3)},")
            append("\"incl\":${num(s.inclinationDeg, 3)},")
            append("\"dist\":${num(s.distanceM, 3)},")
            append("\"fov\":${num(s.fovDeg, 2)},")
            append("\"roll\":${num(s.rollDeg, 2)},")
            append("\"plungeSpeed\":${num(s.plungeSpeed, 2)},")
            append("\"disk\":${s.diskEnabled},")
            append("\"temp\":${num(s.peakTemperatureK, 1)},")
            append("\"rout\":${num(s.outerRadiusM, 2)},")
            append("\"density\":${num(s.opticalDensity, 3)},")
            append("\"turb\":${num(s.turbulence, 3)},")
            append("\"haze\":${num(s.coronalHaze, 3)},")
            append("\"bright\":${num(s.diskBrightness, 3)},")
            append("\"timeScale\":${num(s.timeScale, 2)},")
            append("\"paused\":${s.paused},")
            append("\"beaming\":${num(s.beamingStrength, 3)},")
            append("\"bolo\":${s.bolometricLocked},")
            append("\"interstellar\":${s.thickDiskMode},")
            append("\"edd\":${num(s.eddingtonRatio, 5)},")
            append("\"physT\":${s.physicalDiskTemp},")
            append("\"corona\":${num(s.xrayCorona, 3)},")
            append("\"wind\":${num(s.uvDiskWind, 3)},")
            append("\"blr\":${num(s.broadLineRegion, 3)},")
            append("\"bq\":${num(s.binaryMassRatio, 3)},")
            append("\"bchi1\":${num(s.binarySpin1, 3)},")
            append("\"bchi2\":${num(s.binarySpin2, 3)},")
            append("\"bsep\":${num(s.binarySeparationM, 2)},")
            append("\"bspeed\":${num(s.binaryPlaybackSpeed, 2)},")
            append("\"stars\":${s.starsEnabled},")
            append("\"starBright\":${num(s.starBrightness, 3)},")
            append("\"skyBright\":${num(s.skyBrightness, 3)},")
            append("\"grid\":${s.lensGridEnabled},")
            append("\"jet\":${s.relativisticJetEnabled},")
            append("\"exposure\":${num(s.exposure, 3)},")
            append("\"bloom\":${num(s.bloomStrength, 3)},")
            append("\"quality\":\"${s.quality.jsKey}\",")
            append("\"autoRes\":${s.adaptiveResolution},")
            append("\"eht\":${s.ehtFilterEnabled},")
            append("\"panXDp\":${num(panXDp, 2)},")
            append("\"panYDp\":${num(panYDp, 2)},")
            append("\"dockShiftDp\":${num(dockShiftDp, 2)},")
            append("\"yawRad\":${num(yawRad, 4)},")
            append("\"pitchRad\":${num(pitchRad, 4)}")
            append('}')
        }
    }

    /** Formats a fast camera-only JS call for 60-120 Hz touch gesture frames. */
    fun buildFastCameraCall(
        azimuthDeg: Double,
        inclinationDeg: Double,
        distanceM: Double,
        fovDeg: Double,
        rollDeg: Double,
        panXDp: Double,
        panYDp: Double,
        dockShiftDp: Double,
        yawRad: Double,
        pitchRad: Double,
        modeKey: String
    ): String {
        fun n(v: Double, d: Int = 4): String = String.format(Locale.US, "%.${d}f", v)
        return "window.__antarBridge&&window.__antarBridge.applyCamera(" +
            "${n(azimuthDeg, 3)},${n(inclinationDeg, 3)},${n(distanceM, 3)}," +
            "${n(fovDeg, 2)},${n(rollDeg, 2)},${n(panXDp, 2)},${n(panYDp, 2)}," +
            "${n(dockShiftDp, 2)},${n(yawRad, 4)},${n(pitchRad, 4)},\"$modeKey\");"
    }

    /** Pure-Kotlin RFC-4648 Base64 decoder (zero `android.util.Base64` dependency). */
    internal fun decodeBase64RFC4648(encoded: String): ByteArray {
        val table = BASE64_INV
        var validChars = 0
        var pad = 0
        for (i in encoded.indices) {
            val c = encoded[i].code
            if (c == '='.code) pad++
            else if (c < 128 && table[c] >= 0) validChars++
        }
        val totalQuadChars = validChars + pad
        val outLen = (totalQuadChars / 4) * 3 - pad
        val out = ByteArray(outLen.coerceAtLeast(0))
        var outIdx = 0
        var acc = 0
        var bits = 0
        for (i in encoded.indices) {
            val c = encoded[i].code
            if (c == '='.code) break
            val v = if (c < 128) table[c].toInt() else -1
            if (v < 0) continue
            acc = (acc shl 6) or v
            bits += 6
            if (bits >= 8) {
                bits -= 8
                if (outIdx < out.size) {
                    out[outIdx++] = ((acc ushr bits) and 0xFF).toByte()
                }
            }
        }
        return out
    }

    private val BASE64_INV: ByteArray = ByteArray(128) { -1 }.apply {
        for (i in 'A'.code..'Z'.code) this[i] = (i - 'A'.code).toByte()
        for (i in 'a'.code..'z'.code) this[i] = (i - 'a'.code + 26).toByte()
        for (i in '0'.code..'9'.code) this[i] = (i - '0'.code + 52).toByte()
        this['+'.code] = 62
        this['/'.code] = 63
    }

    private const val NATIVE_CHROME_AND_BRIDGE: String = """
<style id="antar-native-chrome">
  html, body, html.transparent-scene, html.transparent-scene body {
    margin: 0 !important;
    padding: 0 !important;
    width: 100% !important;
    height: 100% !important;
    overflow: hidden !important;
    background: #000000 !important;
    touch-action: none !important;
    user-select: none !important;
    -webkit-user-select: none !important;
  }
  body > :not(#gl) {
    display: none !important;
    visibility: hidden !important;
    opacity: 0 !important;
    pointer-events: none !important;
  }
  #gl {
    position: fixed !important;
    inset: 0 !important;
    width: 100vw !important;
    height: 100vh !important;
    display: block !important;
    pointer-events: none !important;
    touch-action: none !important;
  }
</style>
<script id="antar-native-bridge">
(function() {
  'use strict';
  const DEG = Math.PI / 180;
  document.documentElement.classList.add('transparent-scene');
  if (document.body) {
    document.body.classList.add('hide-ui', 'panel-closed', 'no-diagram', 'no-gw');
  }

  function effectiveDpr() {
    const gl = document.getElementById('gl');
    if (gl && gl.width > 0 && window.innerWidth > 0) {
      return gl.width / window.innerWidth;
    }
    return Math.min(window.devicePixelRatio || 1, 2);
  }

  const bridge = {
    applyCamera: function(azDeg, inclDeg, distM, fovDeg, rollDeg, panXDp, panYDp, dockShiftDp, yawRad, pitchRad, modeKey) {
      const bh = window.__bh;
      if (!bh) return;
      const dpr = effectiveDpr();
      if (modeKey === 'orbit' && (bh.tour.active || bh.cam.mode === 'cinematic')) {
        bh.setMode('orbit');
      }
      if (!bh.plunge.active && modeKey === 'orbit') {
        bh.cam.az = bh.cam.tAz = azDeg * DEG;
        bh.cam.incl = bh.cam.tIncl = inclDeg * DEG;
        bh.cam.dist = bh.cam.tDist = distM;
        bh.params.incl = inclDeg;
        bh.params.dist = distM;
      }
      const nextPanX = -(panXDp + dockShiftDp) * dpr;
      const nextPanY = panYDp * dpr;
      const panOrRollChanged =
        Math.abs(bh.params.roll - rollDeg) > 1e-4 ||
        Math.abs(bh.cam.panX - nextPanX) > 0.05 ||
        Math.abs(bh.cam.panY - nextPanY) > 0.05;
      bh.params.fov = bh.cam.fov = fovDeg;
      bh.params.roll = rollDeg;
      bh.cam.panX = nextPanX;
      bh.cam.panY = nextPanY;
      bh.cam.yaw = bh.cam.tYaw = yawRad;
      bh.cam.pitch = bh.cam.tPitch = pitchRad;
      if (panOrRollChanged && !bh.tour.active) {
        bh.onParam('__view');
      }
    },

    applySettings: function(cfg) {
      const bh = window.__bh;
      if (!bh || !cfg) return;
      const p = bh.params;
      const wantMode = cfg.mode || 'orbit';
      const keepActiveTour = wantMode === 'tour' && bh.tour.active;

      if (!keepActiveTour && cfg.object && cfg.object !== p.object) {
        bh.setObject(cfg.object, true);
      }

      const spinChanged = typeof cfg.spin === 'number' && Math.abs(cfg.spin - p.spin) > 1e-6;
      const binChanged =
        (typeof cfg.bq === 'number' && Math.abs(cfg.bq - p.bq) > 1e-6) ||
        (typeof cfg.bchi1 === 'number' && Math.abs(cfg.bchi1 - p.bchi1) > 1e-6) ||
        (typeof cfg.bchi2 === 'number' && Math.abs(cfg.bchi2 - p.bchi2) > 1e-6) ||
        (typeof cfg.bsep === 'number' && Math.abs(cfg.bsep - p.bsep) > 1e-6);

      if (!keepActiveTour) {
        const keys = [
          'spin','mass','incl','dist','fov','roll','plungeSpeed',
          'disk','temp','rout','density','turb','haze','bright','timeScale','paused',
          'beaming','bolo','interstellar',
          'edd','physT','corona','wind','blr',
          'bq','bchi1','bchi2','bsep','bspeed',
          'stars','starBright','skyBright','grid','jet',
          'exposure','bloom','quality','autoRes','eht'
        ];
        for (let i = 0; i < keys.length; i++) {
          const k = keys[i];
          if (cfg[k] !== undefined) p[k] = cfg[k];
        }
        if (spinChanged) bh.onParam('spin');
        if (p.physT) bh.onParam('physT');
        bh.onParam('quality');
        bh.onParam('eht');
        if (binChanged) bh.onParam('bsep');
        if (p.object === 'merger' && bh.bin) {
          bh.bin.playing = !p.paused;
        }
      } else {
        if (cfg.exposure !== undefined) p.exposure = cfg.exposure;
        if (cfg.bloom !== undefined) p.bloom = cfg.bloom;
        if (cfg.quality !== undefined) p.quality = cfg.quality;
        if (cfg.autoRes !== undefined) p.autoRes = cfg.autoRes;
        if (cfg.paused !== undefined) p.paused = cfg.paused;
      }

      if (wantMode === 'tour') {
        if (!bh.tour.active) bh.startTour();
      } else {
        if (bh.tour.active) bh.stopTour();
        if (wantMode === 'plunge') {
          if (!bh.plunge.active && p.object !== 'merger') {
            bh.cam.az = bh.cam.tAz = (cfg.az !== undefined ? cfg.az : 38) * DEG;
            bh.cam.incl = bh.cam.tIncl = p.incl * DEG;
            bh.cam.dist = bh.cam.tDist = p.dist;
            bh.startPlunge(true);
          }
        } else {
          if (bh.plunge.active || bh.cam.mode !== wantMode) {
            bh.setMode(wantMode);
          }
          if (wantMode === 'orbit') {
            if (cfg.az !== undefined) bh.cam.az = bh.cam.tAz = cfg.az * DEG;
            bh.cam.incl = bh.cam.tIncl = p.incl * DEG;
            bh.cam.dist = bh.cam.tDist = p.dist;
          } else if (wantMode === 'cinematic') {
            bh.cam.cBaseIncl = p.incl * DEG;
            bh.cam.cBaseDist = p.dist;
          }
        }
      }

      const dpr = effectiveDpr();
      bh.cam.fov = p.fov;
      bh.cam.panX = -((cfg.panXDp || 0) + (cfg.dockShiftDp || 0)) * dpr;
      bh.cam.panY = (cfg.panYDp || 0) * dpr;
      if (cfg.yawRad !== undefined) bh.cam.yaw = bh.cam.tYaw = cfg.yawRad;
      if (cfg.pitchRad !== undefined) bh.cam.pitch = bh.cam.tPitch = cfg.pitchRad;
      if (!bh.tour.active) bh.onParam('__sync');
    },

    restartBinary: function() {
      const bh = window.__bh;
      if (!bh) return;
      bh.params.paused = false;
      bh.onParam('bsep');
      if (bh.bin) bh.bin.playing = true;
    },

    snapshot: function() {
      const errEl = document.getElementById('error');
      if (errEl && errEl.style.display === 'flex' && errEl.textContent) {
        return { ready: false, error: errEl.textContent };
      }
      const bh = window.__bh;
      if (!bh) return { ready: false, error: null };
      const ld = document.getElementById('loading');
      const ready = !ld || ld.style.opacity === '0';
      let plungeR = bh.cam.dist;
      let inside = false;
      if (bh.plunge && bh.plunge.active) {
        const s = bh.plunge.s;
        plungeR = bh.P.kerrR(s[0], s[1], s[2], bh.plunge.a);
        inside = plungeR < bh.P.horizon(bh.plunge.a);
      }
      let binSep = bh.params.bsep || 14;
      let binV = 0, binFgw = 0, binTMerge = 0, binMerged = false;
      if (bh.params.object === 'merger' && bh.bin && bh.bin.st) {
        const st = bh.bin.st;
        const secM = 4.07e10 * (1 + bh.params.bq) * 4.925490947e-6;
        binSep = st.sep || 0;
        binV = st.v || 0;
        binFgw = secM > 0 ? (st.fGW / secM) : 0;
        binTMerge = (st.tToMerger || 0) * secM;
        binMerged = !!st.merged;
      }
      let azDeg = (bh.cam.az / DEG) % 360;
      if (azDeg > 180) azDeg -= 360;
      if (azDeg < -180) azDeg += 360;
      const gl = document.getElementById('gl');
      const sc = bh.scale || 0.7;
      return {
        ready: ready,
        error: null,
        fps: Math.round(bh.fps || 60),
        scale: +(sc.toFixed(2)),
        rw: gl ? Math.round(gl.width * sc) : 0,
        rh: gl ? Math.round(gl.height * sc) : 0,
        dist: +(bh.cam.dist.toFixed(3)),
        incl: +((bh.cam.incl / DEG).toFixed(2)),
        az: +(azDeg.toFixed(2)),
        plunge: !!(bh.plunge && bh.plunge.active),
        plungeR: +(plungeR.toFixed(3)),
        plungeTau: bh.plunge ? +(bh.plunge.tau.toFixed(2)) : 0,
        inside: inside,
        tour: !!(bh.tour && bh.tour.active),
        binSep: +(binSep.toFixed(2)),
        binV: +(binV.toFixed(4)),
        binFgw: binFgw,
        binTMerge: binTMerge,
        binMerged: binMerged
      };
    }
  };

  window.__antarBridge = bridge;

  function reportRuntimeError(message) {
    try {
      if (window.AntarHostBridge && typeof window.AntarHostBridge.onRuntimeError === 'function') {
        window.AntarHostBridge.onRuntimeError(String(message || 'Unknown WebGL runtime error'));
      }
    } catch (_) {}
  }
  window.addEventListener('error', function(event) {
    reportRuntimeError((event && event.message) || 'Unhandled JavaScript error');
  });
  window.addEventListener('unhandledrejection', function(event) {
    reportRuntimeError((event && event.reason && event.reason.message) || 'Unhandled JavaScript rejection');
  });

  setInterval(function() {
    if (!window.AntarHostBridge || typeof window.AntarHostBridge.onTelemetry !== 'function') return;
    try {
      const snap = bridge.snapshot();
      window.AntarHostBridge.onTelemetry(JSON.stringify(snap));
    } catch (e) {}
  }, 220);
})();
</script>
"""

    private val KERR_SIMULATION_GZIP_B64: String = listOf(
    "" +
    "" +
    "" +
    "" +
    "" +
    "" +
    "" +
    "" +
    "" +
    "" +
    "" +
    ""
    ).joinToString(separator = "")
}
